import{_ as s,l as i,o as e,c as d,v as o,p as l,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"综合与网表","description":"","frontmatter":{"title":"综合与网表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/synthesis-netlist.md","filePath":"cs/synthesis-netlist.md","lastUpdated":1789023840000}'),h={name:"cs/synthesis-netlist.md"};function T(E,a,A,_,m,u){const r=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="综合与网表" tabindex="-1">综合与网表 <a class="header-anchor" href="#综合与网表" aria-label="Permalink to &quot;综合与网表&quot;">​</a></h1><div class="epigraph"><p>综合把 RTL 的并行行为映射成标准单元或 LUT 的连接：算术变成门，`posedge` 变成触发器，不可综合的延迟与打印被丢掉。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；IEEE Std 1364.1（RTL 综合子集）整理</footer></div><p><a href="/cs/blocking-nonblocking">上一课</a>让仿真与预期硬件对齐。缺口是工具链的下一步：<strong>逻辑综合</strong>——读 RTL 与约束，写出门级网表（Verilog 仍可当交换格式，里面是 <code>AND2</code>、<code>DFF</code> 例化）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>assign y = a + b;</code> 在 RTL 是行为。综合器在库里选行波或 CLA 结构、插入缓冲、做逻辑优化（与<a href="/cs/karnaugh-map">卡诺图</a>同一布尔目标，规模大得多）。缺口不是再讲阻塞赋值，而是：哪些构造被认作组合/时序，哪些被忽略（<code>#5</code>、<code>initial $display</code>）。网表是实例与网的表，不再有 <code>always</code> 调度。</p><p>约束：时钟周期、输入延迟、假路径。没有周期约束，工具不知该用快单元还是省面积——与<a href="/cs/adder-cla">加法器延迟</a>的手工权衡同一问题，改由工具做。</p><h3 id="综合不是「保证等价于所有仿真行为」" tabindex="-1">综合不是「保证等价于所有仿真行为」 <a class="header-anchor" href="#综合不是「保证等价于所有仿真行为」" aria-label="Permalink to &quot;综合不是「保证等价于所有仿真行为」&quot;">​</a></h3><p>语言里可写出综合器不支持或会改语义的结构（如敏感列表不全的 <code>always</code>）。后课形式等价检查才在 RTL 与网表之间建证明。本课承认：综合是带约束的翻译，不是整语言的解释器。</p><p><span class="marginnote">IEEE 1364.1 尝试定义可综合子集。Harris 展示 RTL→门。厂商综合器（Design Compiler、Vivado 等）实现细节不同，本课钉流程角色。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：RTL、工艺库或 FPGA 器件、SDC 一类约束。输出：网表 + 初步时序/面积报告。算术推断：<code>*</code> 可能映射到 FPGA DSP 或 ASIC 乘法器生成器，对应上一单元的树，但结构由工具选。FSM 从 <code>case</code> 状态编码推出。</p>',11)),(e(),l(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RTL%5B%22RTL%20%2B%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SYN%5B%22%E9%80%BB%E8%BE%91%E7%BB%BC%E5%90%88%22%5D%0A%20%20SYN%20--%3E%20NL%5B%22%E9%97%A8%E7%BA%A7%E7%BD%91%E8%A1%A8%22%5D%0A%20%20NL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASTA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>扫描链、时钟门控可在综合插入，后课 DFT 与功耗再展开。本课只看到「功能网表」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>静态时序分析吃的是这张网表加延迟模型。布局布线之后延迟会变，需要再综合或物理优化——后课 FPGA/ASIC 流程。本课把网表定义为综合与 STA 之间的合同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教某 GUI 的按钮，不把高级综合 C++ 当 RTL（那是 HLS 课）。不发明网表格式标准号。晶体管级 SPICE 不在数字综合输出里。</p><p>后课默认：可综合 RTL 变成门与 FF 的网表；延迟数字交给 STA，不在仿真 <code>#delay</code> 里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>综合：RTL+约束 → 标准单元/LUT 网表。</li><li>不可综合构造被丢或拒；<code>+</code>/<code>*</code> 的结构由工具推断。</li><li>下一课用 STA 检查这张网是否满足周期。</li><li>出处：Harris and Harris；IEEE 1364.1。</li></ul>',8))])}const L=s(h,[["render",T]]);export{f as __pageData,L as default};
